class FragmentEvidenceScorer(SourceStage):
    def __init__(self, label, source_cells):
        super().__init__(label, source_cells)
        self.cache, self.errors = {}, []

    def score(self, scope, mid, candidates):
        module = scope.get('frag_rescore')
        if module is None or '_fcache' not in scope:
            return {}
        frame = scope['te'][scope['te'].molecule_id.astype(str) == str(mid)]
        spectra = [dict(mz=np.asarray(r.ms2_mzs, np.float64),
            it=np.asarray(r.ms2_normalized_intensities, np.float64), adduct=r.adduct,
            prec=float(r.precursor_mz), mode=1 if r.ionization_mode == 'positive' else -1)
            for r in frame.itertuples(index=False)][:16]
        if not spectra:
            return {}
        try:
            values = module.score_molecule(spectra, candidates, cache=self.cache)
            return {s: float(v) for s, v in zip(candidates, values) if v is not None and math.isfinite(float(v))}
        except Exception as error:
            self.errors.append(dict(molecule_id=str(mid), error=repr(error)))
            print('GROUP FRAGMENT FAILED: preserve v7c order', mid, repr(error))
            return {}

class MetricIdentityFusion:
    def __init__(self, scope):
        self.scope = scope

    def rank(self, first, second, window):
        return self.scope['metric_fusion'](first, second, self.scope['metric_identity'],
            alpha=self.scope['ALPHA'], offset=self.scope['KRR'], limit=window)

class EvidenceRouter:
    def __init__(self, scope, config, fragments):
        self.scope, self.config, self.fragments = scope, config, fragments
        self.fusion = MetricIdentityFusion(scope)

    @staticmethod
    def coverage(scores, candidates, keys):
        count = 0
        for smile, key in zip(candidates, keys):
            value = scores.get(smile)
            if value is None:
                value = scores.get(key)
            try:
                count += value is not None and math.isfinite(float(value))
            except (TypeError, ValueError):
                pass
        return count

    def group_rescore(self, mid, candidates, original_candidates, scores, ice, gl):
        scope = self.scope
        keys = [scope['chem'].score_key(s) or s for s in candidates]
        formulas = [scope['_form2'](s) for s in candidates]
        groups = {}
        for index, formula in enumerate(formulas):
            groups.setdefault(formula, []).append(index)
        missing = []
        for indices in groups.values():
            smiles = [candidates[i] for i in indices]
            group_keys = [keys[i] for i in indices]
            if len(indices) >= 2 and not self.coverage(ice, smiles, group_keys) and not self.coverage(gl, smiles, group_keys):
                missing.append(indices)
        if not missing:
            return list(candidates), 0
        needed = [candidates[i] for indices in missing for i in indices]
        evidence = self.fragments.score(scope, mid, needed)
        accepted = {}
        for indices in missing:
            if all(candidates[i] in evidence for i in indices):
                accepted.update((candidates[i], evidence[candidates[i]]) for i in indices)
        if not accepted:
            return list(candidates), 0
        score_by_smile = dict(zip(original_candidates, scores))
        aligned_scores = [score_by_smile[s] for s in candidates]
        order = scope['gl_fuse'].rerank_multi(candidates, keys, aligned_scores, formulas,
            [accepted], [self.config.fragment_weight], top_n=len(candidates))
        # Group-slot preservation is a trust boundary, not just a plotting assumption.
        eligible_positions = {i for indices in missing if all(candidates[j] in accepted for j in indices) for i in indices}
        assert all(i == j for i, j in enumerate(order) if i not in eligible_positions)
        return [candidates[i] for i in order], sum(all(candidates[i] in accepted for i in indices) for indices in missing)
    def rerank_row(self, mid, original, *, window, ice_fallback, processed, group=False):
        scope = self.scope
        'Rebuild final metric fusion from same-run prefusion and engine lists.\n\n        ``original`` is the metric-safe reference BEFORE the frozen final overlay,\n        not the E004 final output. The original identity, representative selection,\n        same-formula slot rerank and tail fill are reused without modification.\n        '
        if window not in (40, 80):
            raise ValueError('Only the prespecified 40/80 candidate windows are supported')
        original = list(original)
        audit = {'molecule_id': mid, 'processed': bool(processed), 'branch': 'placeholder', 'candidate_count': 0, 'collapsed_source_votes': 0, 'ice_finite_count': 0, 'gl_finite_count': 0, 'fallback_changed': False, 'fallback_changed_top1': False, 'group_fragment_groups': 0}
        if not processed:
            return (original, audit)
        audit['branch'] = 'no_engine'
        engine = scope['ENG'].get(mid)
        if mid not in scope['PREFUSION_LISTS'] or not engine or (not engine.get('smiles')):
            return (original, audit)
        first = [s for s in scope['PREFUSION_LISTS'][mid] if s and s != 'CCO']
        candidates, scores, collapsed = self.fusion.rank(first, engine['smiles'], window)
        keys = [scope['chem'].score_key(s) or s for s in candidates]
        ice_scores = scope['ICE_SCORES']
        ice = ice_scores.get(mid, {}) if isinstance(ice_scores, dict) else {}
        gl = scope['gl_of'](mid)
        audit.update(branch='unrescored', candidate_count=len(candidates), collapsed_source_votes=collapsed, ice_finite_count=self.coverage(ice, candidates, keys), gl_finite_count=self.coverage(gl, candidates, keys))
        before = list(candidates)
        if ice and gl:
            order = scope['gl_fuse'].rerank_multi(candidates, keys, scores, [scope['_form2'](s) for s in candidates], [{}, gl], [scope['ICE_LAM'], scope['GL_LAM']], top_n=len(candidates))
            candidates = [candidates[i] for i in order]
            audit['branch'] = 'glacier'
        elif ice_fallback and (not gl) and scope.get('FRAG_GAP', {}).get(mid) and (not any((v is not None for v in (ice or {}).values()))):
            order = scope['gl_fuse'].rerank_multi(candidates, keys, scores, [scope['_form2'](s) for s in candidates], [scope['FRAG_GAP'][mid]], [0.5], top_n=len(candidates))
            candidates = [candidates[i] for i in order]
            audit['branch'] = 'frag_gap'
        elif ice_fallback and ice and (not gl):
            order = scope['ice_fuse'].rerank(candidates, keys, scores, [scope['_form2'](s) for s in candidates], ice, lam=scope['ICE_LAM'], top_n=len(candidates))
            candidates = [candidates[i] for i in order]
            audit['branch'] = 'ice_fallback'
        if group and audit['branch'] != 'frag_gap':
            candidates, ng = self.group_rescore(mid, candidates, before, scores, ice, gl)
            audit['group_fragment_groups'] = ng
            if ng:
                audit['branch'] += '+group_fragment'
        result = scope['safe_extend'](candidates[:25], candidates[25:] + original) if candidates else original
        if audit['branch'] == 'ice_fallback':
            without_ice = scope['safe_extend'](before[:25], before[25:] + original) if before else original
            audit['fallback_changed'] = result != without_ice
            audit['fallback_changed_top1'] = result[:1] != without_ice[:1]
        return (result, audit)

'''Independent iteration: method, provenance and guardrails
Audit the actual metric-fusion top40. For competing same-formula groups with missing simulator scores, repeat the original predictor/scoring recipe on the complete comparison group. Keep existing finite scores; fill only missing values. Accept a group only with complete finite coverage, otherwise preserve its Initial01 order. Preserve every untargeted group slot. Prefer the existing GLACIER route, otherwise ICEBERG; fully unsupported spectra remain unchanged. A previously unavailable GLACIER group may be attempted when supported H spectra exist and ICE has no dictionary. Two extra inference budgets of at most 1800 seconds each plus runner grace/startup overhead. This is new evidence, not window expansion or new similarity.
Our contribution is the controlled coverage/deeper-fragment orchestration. The credited @ahmedberatozer predictor packages and Huseyin Emre Aksoy fragment kernels are reused without rewriting their numerical definitions. All authors, links and licences remain above. The iteration audit compares against completed Initial01 from the same run; the earlier research audit/graphs still describe Initial01. A smoke no-op is not hidden validation, but exact identical final predictions should not consume another submission.'''

class EvidenceIteration:
    def __init__(self, experiment):
        self.experiment, self.scope = experiment, experiment.scope
        self.audit = []

    @staticmethod
    def finite(value):
        try:
            return value is not None and math.isfinite(float(value))
        except (TypeError, ValueError):
            return False

    def value(self, evidence, smile, key):
        value = evidence.get(smile)
        return evidence.get(key) if value is None else value

    def fused(self, mid):
        scope = self.scope
        engine = scope['ENG'].get(mid)
        if not engine or not engine.get('smiles') or mid not in scope['PREFUSION_LISTS']:
            return [], [], [], []
        first = [s for s in scope['PREFUSION_LISTS'][mid] if s and s != 'CCO']
        candidates, scores, _ = MetricIdentityFusion(scope).rank(first, engine['smiles'], 40)
        keys = [scope['chem'].score_key(s) or s for s in candidates]
        formulas = [scope['_form2'](s) for s in candidates]
        return candidates, scores, keys, formulas

    def baseline_order(self, mid, candidates, scores, keys, formulas):
        scope = self.scope
        ice, gl = scope['ICE_SCORES'].get(mid, {}), scope['gl_of'](mid)
        if ice and gl:
            return scope['gl_fuse'].rerank_multi(candidates, keys, scores, formulas,
                [{}, gl], [scope['ICE_LAM'], scope['GL_LAM']], top_n=len(candidates))
        frag = scope.get('FRAG_GAP', {}).get(mid)
        if not gl and frag and not any(v is not None for v in (ice or {}).values()):
            return scope['gl_fuse'].rerank_multi(candidates, keys, scores, formulas,
                [frag], [.5], top_n=len(candidates))
        if ice and not gl:
            return scope['ice_fuse'].rerank(candidates, keys, scores, formulas, ice,
                lam=scope['ICE_LAM'], top_n=len(candidates))
        return list(range(len(candidates)))

    def preserve_slots(self, order, eligible):
        assert sorted(order) == list(range(len(order)))
        assert all(i == j for i,j in enumerate(order) if i not in eligible)

    def finish(self, rows, control, name, details):
        frame = pd.DataFrame(rows, columns=['molecule_id','smiles'])
        active = set(self.scope['te'].molecule_id.astype(str))
        SubmissionBuilder(self.scope).validate(frame, control, active)
        frame.to_csv('submission.csv', index=False)
        comparison = pd.DataFrame(dict(molecule_id=control.molecule_id,
            changed=control.smiles != frame.smiles,
            changed_top1=control.smiles.str.split(';').str[0] != frame.smiles.str.split(';').str[0]))
        comparison.to_csv('iteration_vs_0441.csv', index=False)
        pd.DataFrame(self.audit).to_csv('iteration_group_audit.csv', index=False)
        report = dict(experiment=name, changed_rows=int(comparison.changed.sum()),
            changed_top1=int(comparison.changed_top1.sum()), details=details, measured_score=None,
            control_sha256=hashlib.sha256(Path('submission_0441_control.csv').read_bytes()).hexdigest(),
            submission_sha256=hashlib.sha256(Path('submission.csv').read_bytes()).hexdigest())
        Path('iteration_audit.json').write_text(json.dumps(report, indent=2))
        print(json.dumps(report, indent=2))
        if not report['changed_rows']:
            print('NO-OP versus Initial 01: do not spend a second submission on identical predictions.')
        return report

    def control(self):
        Path('submission_0441_control.csv').write_bytes(Path('submission.csv').read_bytes())
        return pd.read_csv('submission.csv', dtype=str, keep_default_na=False)

class FusionFirstCoverage(EvidenceIteration):
    def prepare(self, control):
        scope = self.scope
        self.audit = []
        self.plans, self.targets = {}, {'gl':{}, 'ice':{}}
        frames = {str(mid):frame for mid,frame in scope['te'].groupby('molecule_id',sort=False)}
        for row in control.itertuples(index=False):
            mid = row.molecule_id
            if mid not in frames:
                continue
            candidates, scores, keys, formulas = self.fused(mid)
            if not candidates:
                continue
            order = self.baseline_order(mid, candidates, scores, keys, formulas)
            ordered = [candidates[i] for i in order]
            assert scope['safe_extend'](ordered[:25],ordered[25:]+row.smiles.split(';')) == row.smiles.split(';'), 'Initial 01 reconstruction differs'
            self.plans[mid] = (candidates,scores,keys,formulas,order)
            ice, gl = scope['ICE_SCORES'].get(mid,{}), scope['gl_of'](mid)
            supported_gl = bool(((frames[mid].ionization_mode == 'positive') & (frames[mid].adduct == '[M+H]+')).any())
            supported_ice = bool(((frames[mid].ionization_mode == 'positive') & frames[mid].adduct.isin(['[M+H]+','[M+Na]+'])).any())
            stage = 'gl' if gl or (supported_gl and not ice) else 'ice'
            supported = supported_gl if stage == 'gl' else supported_ice
            evidence = gl if stage == 'gl' else ice
            groups = {}
            for i, formula in enumerate(formulas):
                groups.setdefault(formula,[]).append(i)
            for formula,indices in groups.items():
                if len(indices) < 2:
                    continue
                missing = sum(not self.finite(self.value(evidence,candidates[i],keys[i])) for i in indices)
                if not missing:
                    continue
                self.audit.append(dict(molecule_id=mid, formula=formula, stage=stage,
                    candidates=len(indices), missing_scores=missing, supported=supported, accepted=False))
                if supported:
                    self.targets[stage].setdefault(mid,[]).append(indices)
        return frames

    def predict(self):
        scope = self.scope
        output = {'gl':{},'ice':{}}
        budget = 1800 if scope['IS_RERUN'] else 120
        for stage in ('gl','ice'):
            candidate_map = {}
            for mid,groups in self.targets[stage].items():
                candidates = self.plans[mid][0]
                candidate_map[mid] = [candidates[i] for indices in groups for i in indices]
            if not candidate_map:
                continue
            items = scope['ice_fuse'].build_ice_input(scope['te'], candidate_map)
            if stage == 'gl':
                items = [dict(item,spectra=[s for s in item['spectra'] if s.get('adduct')=='[M+H]+']) for item in items]
            items = [item for item in items if item['spectra']]
            workdir = '/kaggle/working/fusion_coverage_' + stage
            if stage == 'gl':
                output[stage] = scope['gl_fuse'].run_gl(scope['GL_PKG'], items, workdir=workdir,
                    device='cuda', budget_s=budget, site='/kaggle/working/ice_site',
                    wheels=str(Path(scope['ICE_PKG'])/'wheels'), extra_args=['--any-rdkit'])
            else:
                output[stage] = scope['ice_fuse'].run_ice(scope['ICE_PKG'], items, workdir=workdir,
                    device='cuda', budget_s=budget, site='/kaggle/working/ice_site', extra_args=['--any-rdkit'])
        return output

    def complete_group(self, indices, candidates, keys, original, predicted):
        combined = {}
        for i in indices:
            value = self.value(original,candidates[i],keys[i])
            if not self.finite(value):
                value = self.value(predicted,candidates[i],keys[i])
            if not self.finite(value):
                return {}
            combined[candidates[i]] = float(value)
        return combined

    def run(self):
        control = self.control()
        self.prepare(control)
        predicted = self.predict()
        rows, accepted_groups = [], 0
        for row in control.itertuples(index=False):
            mid, original = row.molecule_id, row.smiles.split(';')
            revised = list(original)
            if mid in self.plans:
                candidates,scores,keys,formulas,baseline_order = self.plans[mid]
                current = [candidates[i] for i in baseline_order]
                positions = {i:j for j,i in enumerate(baseline_order)}
                for stage in ('gl','ice'):
                    old = self.scope['gl_of'](mid) if stage=='gl' else self.scope['ICE_SCORES'].get(mid,{})
                    evidence, eligible = {}, set()
                    for indices in self.targets[stage].get(mid,[]):
                        complete = self.complete_group(indices,candidates,keys,old,predicted[stage].get(mid,{}))
                        if complete:
                            evidence.update(complete)
                            eligible.update(positions[i] for i in indices)
                            accepted_groups += 1
                            formula = formulas[indices[0]]
                            next(a for a in self.audit if a['molecule_id']==mid and a['formula']==formula)['accepted'] = True
                    if evidence:
                        by_smile = dict(zip(candidates,scores))
                        key_by_smile = dict(zip(candidates,keys))
                        form_by_smile = dict(zip(candidates,formulas))
                        order = self.scope['gl_fuse'].rerank_multi(current,[key_by_smile[s] for s in current],
                            [by_smile[s] for s in current],[form_by_smile[s] for s in current],
                            [evidence],[self.scope['GL_LAM'] if stage=='gl' else self.scope['ICE_LAM']],top_n=len(current))
                        self.preserve_slots(order,eligible)
                        current = [current[i] for i in order]
                if any(a['accepted'] for a in self.audit if a['molecule_id']==mid):
                    revised = self.scope['safe_extend'](current[:25],current[25:]+original)
            rows.append((mid,';'.join(revised)))
        return self.finish(rows,control,'fusion_first_coverage',dict(target_groups=len(self.audit),
            accepted_groups=accepted_groups, supported_groups=sum(a['supported'] for a in self.audit),
            per_simulator_budget_seconds=1800 if self.scope['IS_RERUN'] else 120))
