def _meta(adduct, nce):
    return {'name': 'q', 'collision_energy': float(nce), 'instrument': 'HCD', 'precursor_mode': adduct}


def make_metabolite(smi, adduct='[M+H]+', nce=40.0):
    try:
        m = _S['Metabolite'](smi)
        m.create_molecular_structure_graph()
        m.compute_graph_attributes(_S['node'], _S['bond'])
        m.add_metadata(_meta(adduct, nce), _S['setup_enc'], _S['rt_enc'])
        m.fragment_MOL(depth=1)
        return m
    except Exception:
        return None


def predict(m, adduct, nce):
    m.add_metadata(_meta(adduct, nce), _S['setup_enc'], _S['rt_enc'])
    with _S['torch'].no_grad():
        out = _S['sim'].simulate_and_score(m, _S['model'], 'compiled_probsALL', query_peaks=None)
    p = out['sim_peaks']
    return np.asarray(p['mz'], float), np.asarray(p['intensity'], float)


# ------------------------------------------------------------------------------------------ similarity
def _clean(mz, it, prec, floor=0.01, topk=150):
    mz = np.asarray(mz, float); it = np.asarray(it, float)
    k = (mz <= prec + 1.0) & np.isfinite(it) & (it > 0)
    mz, it = mz[k], it[k]
    if len(it) == 0:
        return mz, it
    k = it >= floor * it.max()
    mz, it = mz[k], it[k]
    if len(it) > topk:
        o = np.argsort(-it)[:topk]; mz, it = mz[o], it[o]
    o = np.argsort(mz)
    return mz[o], it[o]


def _weight(p):
    p = p / p.sum()
    s = -np.sum(p * np.log(p))
    if s < 3.0:
        p = p ** (0.25 + 0.25 * s); p = p / p.sum()
    return p


def entropy_sim(mz1, i1, mz2, i2, tol=0.01):
    """Weighted spectral entropy similarity (Li et al. 2021), greedy peak matching within tol Da."""
    if len(mz1) == 0 or len(mz2) == 0:
        return 0.0
    a = _weight(np.asarray(i1, float)); b = _weight(np.asarray(i2, float))
    used = np.zeros(len(mz2), bool); merged = []
    ua = np.zeros(len(mz1), bool)
    for i in np.argsort(-a):
        j0 = np.searchsorted(mz2, mz1[i] - tol); j1 = np.searchsorted(mz2, mz1[i] + tol, 'right')
        best, bj = -1.0, -1
        for j in range(j0, j1):
            if not used[j] and b[j] > best:
                best, bj = b[j], j
        if bj >= 0:
            used[bj] = True; ua[i] = True; merged.append(a[i] + b[bj])
    rest = np.concatenate([a[~ua], b[~used], np.asarray(merged)])
    ab = rest / 2.0
    ab = ab[ab > 0]
    h = lambda p: -np.sum(p * np.log(p))
    sa, sb, sab = h(a[a > 0]), h(b[b > 0]), h(ab)
    return float(max(0.0, 1.0 - (2 * sab - sa - sb) / np.log(4)))


def nce_of(ce_ev, prec):
    try:
        v = np.atleast_1d(np.asarray(ce_ev, float))
        ev = float(np.nanmean(v)) if len(v) else 30.0
    except Exception:
        ev = 30.0
    if not np.isfinite(ev):
        ev = 30.0
    return float(np.clip(ev * 500.0 / max(float(prec), 50.0), 5.0, 100.0))


def score_candidates(queries, cands, max_cands=25, log_every=50, deadline=None, modes=MODES):
    """queries: DataFrame with molecule_id, ms2_mzs, ms2_normalized_intensities, precursor_mz, adduct,
    collision_energy_ev. cands: {mid: [smiles]} (put the molecules that matter most first; a deadline stops the loop).
    modes: precursor types to score (subset of MODES). Returns {mid: {smiles: score or None}}."""
    setup()
    t0 = time.time(); out = {}; n_pred = 0
    groups = {str(m): g for m, g in queries.groupby('molecule_id')}
    for gi, (mid, cs) in enumerate(cands.items()):
        if deadline is not None and time.time() > deadline:
            print(f'fiora deadline reached after {gi} molecules', flush=True)
            break
        g = groups.get(str(mid))
        if g is None:
            continue
        specs = []
        for r in g.itertuples():
            if r.adduct not in modes:
                continue
            mz, it = _clean(r.ms2_mzs, r.ms2_normalized_intensities, r.precursor_mz)
            if len(mz):
                specs.append((r.adduct, round(nce_of(r.collision_energy_ev, r.precursor_mz), 1), mz, it))
        if not specs:
            continue
        conds = sorted(set((a, n) for a, n, _, _ in specs))
        res = {}
        for smi in cs[:max_cands]:
            m = make_metabolite(smi, *conds[0])
            if m is None:
                res[smi] = None; continue
            pred = {}
            try:
                for a, n in conds:
                    pred[(a, n)] = predict(m, a, n); n_pred += 1
            except Exception:
                res[smi] = None; continue
            sims = []
            for a, n, mz, it in specs:
                pm, pi = pred[(a, n)]
                o = np.argsort(pm)
                sims.append(entropy_sim(mz, it, pm[o], pi[o]))
            res[smi] = float(np.mean(sims)) if sims else None
        out[mid] = res
        if (gi + 1) % log_every == 0:
            print(f'  fiora {gi+1}/{len(cands)} molecules, {n_pred} predictions, {time.time()-t0:.0f}s', flush=True)
    print(f'fiora done: {len(out)} molecules, {n_pred} predictions, {time.time()-t0:.0f}s', flush=True)
    return out
