def lead_chunks(its, n_chunks, chunk_jobs=3000):
    out, cur, jobs, done = [], [], 0, 0
    for it in its:
        conds = set()
        for sp in it.get('spectra') or []:
            if sp.get('ce_units') == 'NCE':
                v = [float(x) for x in re.findall(r'[0-9]+\.?[0-9]*', str(sp.get('ce_orig')))]
                ce = float(np.mean(v)) if v else float('nan')
            else:
                ev = sp.get('ce_ev')
                ce = float(np.mean(ev)) if ev is not None and len(ev) else float('nan')
            if np.isfinite(ce):
                conds.add((sp.get('adduct'), max(5.0, float(np.round(ce / 5.0) * 5.0))))
            else:
                conds.update((sp.get('adduct'), c) for c in (20.0, 40.0, 60.0))
        n = len(dict.fromkeys(it.get('cands') or [])) * len(conds)
        if n == 0:
            continue
        cur.append(it); jobs += n
        if jobs >= chunk_jobs:
            out += cur; cur, jobs, done = [], 0, done + 1
            if done >= n_chunks:
                return out
    return out + cur
