        return _CMF2(_Ch2.MolFromSmiles(s))
    except Exception:
        return s

def fuse3(v_smis, e_smis, e_keys, d_smis=None, n=60):
    sc, smi_of = {}, {}
    # 1. Base candidates
    for r, s in enumerate(v_smis, 1):
        k = chem.score_key(s) or s
        sc[k] = sc.get(k, 0.0) + 1.0 / (KRR + r); smi_of.setdefault(k, s)
    # 2. Engine supplementary candidates (PairTail enhanced)
    for r, (s, k) in enumerate(zip(e_smis, e_keys), 1):
        if not k:
            continue
        sc[k] = sc.get(k, 0.0) + ALPHA / (KRR + r); smi_of.setdefault(k, s)
    # 3. Mass-verified DreaMS candidates (adaptive injection for low library confidence)
    if d_smis:
        for r, s in enumerate(d_smis, 1):
            k = chem.score_key(s) or s
            if k not in sc:
                sc[k] = BETA / (KRR + r)
                smi_of.setdefault(k, s)
            else:
                sc[k] += BETA / (KRR + r)
    order = sorted(sc, key=lambda k: -sc[k])[:n]
    return [smi_of[k] for k in order], order, [sc[k] for k in order]

if ENG:
    v4 = pd.read_csv('submission.csv')
    changed = n_ice = 0; out = []
    for mid, s in zip(v4.molecule_id, v4.smiles):
        vs = [x for x in s.split(';') if x and x != 'CCO']
        e = ENG.get(str(mid))
        if e and e['smiles']:
            d_cands = DREAMS_CANDS.get(str(mid), [])
            lib_conf = BASE.get(mid, ([], [], 0.0))[2] if mid in BASE else 0.0

            # Adaptive Fusion: Inject DreaMS candidates when library confidence < 0.35 (Class 2 & 3)
            if lib_conf < 0.35 and d_cands:
                fsm, fk, fsc = fuse3(vs, e['smiles'], e['keys'], d_smis=d_cands[:8], n=60)
            else:
                fsm, fk, fsc = fuse3(vs, e['smiles'], e['keys'], d_smis=None, n=60)

            ice = ICE_SCORES.get(str(mid), {}) if isinstance(ICE_SCORES, dict) else {}
            if ice:
                try:
                    o = ice_fuse.rerank(fsm, fk, fsc, [_form2(x) for x in fsm], ice, lam=ICE_LAM, top_n=len(fsm))
                    _g = gl_of(mid)
                    if _g:
                        o = gl_fuse.rerank_multi(fsm, fk, fsc, [_form2(x) for x in fsm], [ice, _g], [ICE_LAM, GL_LAM], top_n=len(fsm))
                    n_ice += int(o[:25] != list(range(min(25, len(o)))))
                    fsm = [fsm[i] for i in o]
                except Exception as ex:
                    print('fused ICE rerank failed', mid, repr(ex))

            # Strict Metric-Exact Tautomer Canonical Deduplication
            clean_cands = []
            seen_keys = set()
            for cand in fsm:
                k = chem.score_key(cand) or cand
                if k not in seen_keys:
                    seen_keys.add(k)
                    clean_cands.append(cand)
                    if len(clean_cands) == 25:
                        break

            # Backfill from vs if unique candidates < 25
            if len(clean_cands) < 25:
                for cand in vs:
                    k = chem.score_key(cand) or cand
                    if k not in seen_keys:
                        seen_keys.add(k)
                        clean_cands.append(cand)
                        if len(clean_cands) == 25:
                            break

            # Absolute Rank-1 Shield: If library match is confident (lv >= 0.60), lock Rank 1
            if lib_conf >= 0.60 and bool(vs):
                top1_orig = vs[0]
                if clean_cands and clean_cands[0] != top1_orig:
                    clean_cands = [top1_orig] + [c for c in clean_cands if c != top1_orig]

            changed += int(bool(vs) and clean_cands[:1] != vs[:1])
            vs = clean_cands[:25]
        out.append((mid, ';'.join(vs[:25]) if vs else 'CCO'))

    fs = pd.DataFrame(out, columns=['molecule_id', 'smiles'])
    assert len(fs) == len(v4) and fs.molecule_id.is_unique and fs.smiles.notna().all()
    assert fs.smiles.map(lambda s: len(s.split(';'))).max() <= 25
    fs.to_csv('submission.csv', index=False)
    print('v4 PairTail DreaMS Champion fusion written; top-1 changed in', changed, '| ICE reordered', n_ice, f'{time.time()-T0:.0f}s')

