def adduct_table():
    M = {"C": 12.0, "H": 1.00782503207, "N": 14.0030740048, "O": 15.9949146196,
         "Na": 22.9897692809, "K": 38.96370668, "Cl": 34.96885268, "Br": 78.9183371}
    E = 0.00054857990
    proton = M["H"] - E
    h2o = 2 * M["H"] + M["O"]
    nh4 = M["N"] + 4 * M["H"]
    formate = M["C"] + 2 * M["H"] + 2 * M["O"]
    acetate = 2 * M["C"] + 4 * M["H"] + 2 * M["O"]
    return {
        "[M+H]+": (1, 1, proton), "[M+NH4]+": (1, 1, nh4 - E), "[M+Na]+": (1, 1, M["Na"] - E),
        "[M+K]+": (1, 1, M["K"] - E), "[M-H2O+H]+": (1, 1, proton - h2o), "[M]+": (1, 1, -E),
        "[M-H]-": (1, 1, -proton), "[M-H2O-H]-": (1, 1, -proton - h2o),
        "[M+CH2O2-H]-": (1, 1, formate - proton), "[M+C2H4O2-H]-": (1, 1, acetate - proton),
        "[M+Cl]-": (1, 1, M["Cl"] + E), "[M+Br]-": (1, 1, M["Br"] + E), "[M]-": (1, 1, E),
        "[2M+H]+": (2, 1, proton), "[2M+Na]+": (2, 1, M["Na"] - E), "[2M-H]-": (2, 1, -proton),
        "[2M+CH2O2-H]-": (2, 1, formate - proton),
    }

_ADDUCTS = adduct_table()
_POS_CONF = ("[M+H]+", "[M+Na]+", "[M+NH4]+", "[M+K]+", "[M-H2O+H]+", "[M]+", "[2M+H]+", "[2M+Na]+")
_NEG_CONF = ("[M-H]-", "[M+Cl]-", "[M+CH2O2-H]-", "[M+C2H4O2-H]-", "[M-H2O-H]-", "[M]-", "[2M-H]-", "[M+Br]-")


def neutral_of(mz, adduct, table=None):
    spec = (table or _ADDUCTS).get(str(adduct))
    if spec is None:
        return float("nan")
    n, z, d = spec
    return (float(mz) * z - d) / n


def reconcile_targets(mzs, adducts, declared=None):
    """Majority neutral mass, after snapping mislabeled adducts. A second mass is returned only when another cluster is supported."""
    mzs = np.asarray(mzs, np.float64)
    adducts = [str(a) for a in adducts]
    if declared is None:
        declared = np.array([neutral_of(mz, a) for mz, a in zip(mzs, adducts)], np.float64)
    else:
        declared = np.asarray(declared, np.float64)
    ok = np.isfinite(declared) & np.isfinite(mzs) & (mzs > 0)
    if int(ok.sum()) == 0:
        return []
    base = declared[ok]
    med = float(np.median(base))
    if np.all(np.abs(base - med) <= abs(med) * 15.0 / 1e6):
        return [med]
    fixed = declared.copy()
    for i in np.where(ok & (np.abs(declared - med) > abs(med) * 15.0 / 1e6))[0]:
        conf = _POS_CONF if "+" in adducts[i] else _NEG_CONF
        best, bestd = float(declared[i]), abs(float(declared[i]) - med)
        for a in conf:
            nm = neutral_of(mzs[i], a)
            if nm == nm and abs(nm - med) < bestd:
                best, bestd = nm, abs(nm - med)
        if bestd <= abs(med) * 10.0 / 1e6:
            fixed[i] = best
    med2 = float(np.median(fixed[ok]))
    still = np.where(ok & (np.abs(fixed - med2) > abs(med2) * 15.0 / 1e6))[0]
    targets = [med2]
    if len(still) == 0:
        return targets
    conf_of = []
    for i in still:
        conf = _POS_CONF if "+" in adducts[int(i)] else _NEG_CONF
        opts = []
        for a in conf:
            nm = neutral_of(mzs[int(i)], a)
            if nm == nm:
                opts.append(nm)
        conf_of.append(opts)
    best_t, best_n = None, 0
    for opts in conf_of:
        for t in opts:
            tb = abs(t) * 10.0 / 1e6
            n = 0
            for opts2 in conf_of:
                if any(abs(nm - t) <= tb for nm in opts2):
                    n += 1
            if n > best_n:
                best_n, best_t = n, float(t)
    n_spec = int(ok.sum())
    if best_t is not None and abs(best_t - med2) > abs(med2) * 30.0 / 1e6:
        if best_n >= 2 or (best_n >= 1 and n_spec <= 2):
            targets.append(float(best_t))
    return targets


def _rank_one(spectra, target):
    C, X, F, names, info = V.run(spectra, target)
    lib_max = float(info.get("lib_max", 0.0))
    smis, keys, scs, forms, pids = [], [], [], [], []
    if len(C.pid):
        score = rank_score(np.concatenate([X, F], 1), list(FEATURES) + list(names))
        order = np.argsort(-score, kind="stable")
        seen = set()
        for i in order:
            k = C.key[i]
            if k in seen:
                continue
            seen.add(k)
            smis.append(C.smiles[i]); keys.append(k); scs.append(float(score[i]))
            forms.append(C.formula[i]); pids.append(int(C.pid[i]))
            if len(smis) >= TOPN:
                break
    return smis, keys, lib_max, scs, forms, pids


def _merge_runs(a, b):
    """Reciprocal-rank union of two mass windows. Library-lock uses the primary window only."""
    sm_a, k_a, lib_a, sc_a, fo_a, pid_a = a
    sm_b, k_b, lib_b, sc_b, fo_b, pid_b = b
    sc, meta = {}, {}
    for r, (s, k, fo, pid) in enumerate(zip(sm_a, k_a, fo_a, pid_a), 1):
        sc[k] = sc.get(k, 0.0) + 1.0 / (3.0 + r)
        meta.setdefault(k, (s, fo, pid))
    for r, (s, k, fo, pid) in enumerate(zip(sm_b, k_b, fo_b, pid_b), 1):
        sc[k] = sc.get(k, 0.0) + 1.0 / (3.0 + r)
        meta.setdefault(k, (s, fo, pid))
    order = sorted(sc, key=lambda k: -sc[k])[:TOPN]
    return ([meta[k][0] for k in order], order, lib_a,
            [float(sc[k]) for k in order], [meta[k][1] for k in order], [meta[k][2] for k in order])

