                return 0.0
    return 0.0

def _tail_clean(smis, keys, clean_map):
    """Blend cleaned-spectrum entropy into ranks 6-25. Ranks 1-5 stay on the fusion order."""
    if len(smis) <= 5 or not clean_map:
        return smis, keys
    head_s, head_k = smis[:5], keys[:5]
    tail_s, tail_k = smis[5:], keys[5:]
    sc = np.array([float(clean_map.get(k, 0.0)) for k in tail_k], np.float64)
    if len(sc) < 2 or float(sc.std()) < 1e-8:
        return smis, keys
    z = (sc - sc.mean()) / (sc.std() + 1e-9)
    base = np.array([1.0 / (3.0 + r) for r in range(6, 6 + len(tail_s))], np.float64)
    bz = (base - base.mean()) / (base.std() + 1e-9)
    order = np.argsort(-(bz + 0.15 * z), kind="stable")
    return head_s + [tail_s[i] for i in order], head_k + [tail_k[i] for i in order]

def _diversify(smis, keys, forms, gl, start=7, cap=5, zgap=0.5):
    """In ranks 8-25, keep at most `cap` structures of a formula whose GLACIER z-gap is under 0.5."""
    n = len(smis)
    if n <= start or not isinstance(gl, dict) or not gl:
        return smis, keys
    byf = {}
    for i, f in enumerate(forms):
        byf.setdefault(f, []).append(i)
    uncertain = set()
    for f, idx in byf.items():
        vals = []
        for i in idx:
            v = gl.get(smis[i])
            if v is None:
                v = gl.get(keys[i])
            try:
                fv = float(v)
            except (TypeError, ValueError):
                continue
            if fv == fv:
                vals.append(fv)
        if len(vals) < 2:
            uncertain.add(f)
            continue
        a = np.asarray(vals, np.float64)
        sd = float(a.std(ddof=1))
        if sd < 1e-12:
            uncertain.add(f)
            continue
        z = np.sort((a - a.mean()) / sd)
        if float(z[-1] - z[-2]) < zgap:
            uncertain.add(f)
    cnt, kept, rest = {}, [], []
    for i in range(n):
        f = forms[i]
        if i >= start and f in uncertain and cnt.get(f, 0) >= cap:
            rest.append(i)
        else:
            kept.append(i)
            cnt[f] = cnt.get(f, 0) + 1
    order = kept + rest
    return [smis[i] for i in order], [keys[i] for i in order]

def _dreams_interleave(smis, keys, hits, n=25, head=7):
    """Put DreaMS hits on even ranks from 8 downward, leaving the current tail on the odd ranks."""
    if not hits or len(smis) <= head:
        return smis[:n], keys[:n]
    head_s, head_k = smis[:head], keys[:head]
    seen = set(head_k)
    tail = [(s, k) for s, k in zip(smis[head:], keys[head:]) if k not in seen]
    dd, ds = [], set()
    for s, k in hits:
        if k in seen or k in ds:
            continue
        ds.add(k)
        dd.append((s, k))
    out_s, out_k = list(head_s), list(head_k)
    seen2 = set(out_k)
    ti = di = 0
    while len(out_s) < n and (ti < len(tail) or di < len(dd)):
        pos = len(out_s) + 1
        take_d = di < len(dd) and (pos % 2 == 0 or ti >= len(tail))
        if take_d:
            s, k = dd[di]; di += 1
        elif ti < len(tail):
            s, k = tail[ti]; ti += 1
        else:
            break
        if k in seen2:
            continue
        out_s.append(s); out_k.append(k); seen2.add(k)
    return out_s[:n], out_k[:n]

def _build_dreams_hits(te):
    """Cosine retrieval against Enveda-180 DreaMS embeddings, restricted to the reconciled neutral-mass window."""
    import importlib.util
    import gc
    DREAMS_PY = find("dreams_minimal_model.py")
    DREAMS_PT = find("embedding_model_state_dict.pt")
    DREAMS_NPY = find("Enveda180_DreaMS_embeddings.npy")
    DREAMS_IDX = find("Enveda180_DreaMS_index.parquet")
    spec = importlib.util.spec_from_file_location("dreams_minimal_model", DREAMS_PY)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    device = "cuda" if torch.cuda.is_available() else "cpu"
    gc.collect()
    try:
        torch.cuda.empty_cache()
    except Exception:
        pass
    model = mod.load_model(DREAMS_PT, device=device)
    xs, owners = [], []
    for row in te.itertuples(index=False):
        try:
            xs.append(mod.preprocess_spectrum(np.asarray(row.ms2_mzs), np.asarray(row.ms2_normalized_intensities), float(row.precursor_mz)))
            owners.append(row.molecule_id)
        except Exception:
            continue
    acc = {}
    if xs:
        embs = []
        for i in range(0, len(xs), 64):
            embs.append(mod.embed_preprocessed(model, np.stack(xs[i:i + 64])))
        E = np.concatenate(embs, axis=0)
        for mid, e in zip(owners, E):
            acc.setdefault(mid, []).append(e)
    del model, xs
    gc.collect()
    try:
        torch.cuda.empty_cache()
    except Exception:
        pass
    if not acc:
        return {}
    idx = pd.read_parquet(DREAMS_IDX, columns=["normalized_smiles", "inchikey14", "precursor_mz", "adduct", "ionization_mode"])
    ref = np.load(DREAMS_NPY, mmap_mode="r")
    if len(idx) != len(ref):
        raise RuntimeError(f"DreaMS index {len(idx)} != embeddings {len(ref)}")
    nm = np.full(len(idx), np.nan, np.float64)
    ad = idx.adduct.astype(str).to_numpy()
    mz = idx.precursor_mz.to_numpy(np.float64)
    for a, (n, z, d) in _ADDUCTS.items():
        m = ad == a
        if m.any():
            nm[m] = (mz[m] * z - d) / n
    pol = np.where(idx.ionization_mode.astype(str).to_numpy() == "positive", 1, -1).astype(np.int8)
    valid = np.isfinite(nm)
    vidx = np.where(valid)[0]
    order = np.argsort(nm[vidx], kind="mergesort")
    sorted_idx = vidx[order]
    sorted_nm = nm[sorted_idx]
    smiles = idx.normalized_smiles.astype(str).to_numpy()
    iks = idx.inchikey14.astype(str).to_numpy()
    dev = torch.device(device)
    by_mid = {}
    for mid, sub in te.groupby("molecule_id", sort=False):
        qrows = acc.get(mid)
        if not qrows:
            continue
        targets = reconcile_targets(sub.precursor_mz.values.astype(np.float64), sub.adduct.astype(str).values, sub.nm.values.astype(np.float64) if "nm" in sub.columns else None)
        if not targets:
            continue
        modes = set(np.where(sub.ionization_mode.astype(str).values == "positive", 1, -1).tolist())
        want_pol = modes.pop() if len(modes) == 1 else None
        chosen = []
        for t in targets:
            tol = abs(float(t)) * 10.0 / 1e6
            lo = int(np.searchsorted(sorted_nm, float(t) - tol, "left"))
            hi = int(np.searchsorted(sorted_nm, float(t) + tol, "right"))
            if hi <= lo:
                continue
            sl = sorted_idx[lo:hi]
            if want_pol is not None:
                sl = sl[pol[sl] == want_pol]
            if len(sl) > 40000:
                pick = np.argsort(np.abs(nm[sl] - float(t)))[:40000]
                sl = sl[pick]
            if len(sl):
                chosen.append(sl)
        if not chosen:
            continue
        sl = np.unique(np.concatenate(chosen))
        q = torch.as_tensor(np.mean(qrows, axis=0), dtype=torch.float32, device=dev)
        q = torch.nn.functional.normalize(q, dim=0)
        r = torch.as_tensor(np.asarray(ref[sl], np.float32), device=dev)
        r = torch.nn.functional.normalize(r, dim=1)
        sim = (r @ q).detach().cpu().numpy()
        del q, r
        best = {}
        for j, s in enumerate(sim):
            s = float(s)
            if s < 0.60:
                continue
            i = int(sl[j])
            key = iks[i]
            if key not in best or s > best[key][0]:
                best[key] = (s, smiles[i])
        if not best:
            continue
        ranked = sorted(best.values(), key=lambda x: -x[0])[:12]
        hits = []
        seen = set()
        for s, smi in ranked:
            if not smi or smi == "nan":
                continue
            k = chem.score_key(smi) or smi
            if k in seen:
                continue
            seen.add(k)
            hits.append((smi, k))
        if hits:
            by_mid[str(mid)] = hits
    del ref
    print(f"DreaMS mass-window hits for {len(by_mid)} molecules", flush=True)
    return by_mid

