                prec_mz = float(getattr(spec_row, 'precursor_mz', 0.0))
                if adduct == '[M+H]+':
                    target_neutral = prec_mz - 1.007276
                elif adduct == '[M-H]-':
                    target_neutral = prec_mz + 1.007276
                elif adduct == '[M+Na]+':
                    target_neutral = prec_mz - 22.989218
                else:
                    target_neutral = prec_mz - 1.007276

                delta_m = target_neutral * 10e-6
                mass_mask = (dreams_np_mass >= target_neutral - delta_m) & (dreams_np_mass <= target_neutral + delta_m)
                matching_indices = np.where(mass_mask)[0]

                if len(matching_indices) > 0:
                    for idx in matching_indices:
                        smi = dreams_np_smiles[idx]
                        k = chem.score_key(smi) or smi
                        if k not in seen_keys:
                            seen_keys.add(k)
                            raw_smis.append(smi)
                            if len(raw_smis) >= 25:
                                break
                    n_injected += 1

            sub_rows.append((mid, ';'.join(raw_smis[:25]) if raw_smis else 'CCO'))

        sub_df = pd.DataFrame(sub_rows, columns=['molecule_id', 'smiles'])
        sub_df.to_csv('submission.csv', index=False)
        print(f'V18 Sovereign: DreaMS tail injection completed for {n_injected} candidate-sparse molecules!')
except Exception as _e:
    print(f'V18 Sovereign: Note: DreaMS tail injection pass bypassed ({_e})')

    print('b421 fused submission written; top-1 changed in', changed, '| ICE reordered', n_ice, '| CELL19_ICE', CELL19_ICE, f'{time.time()-T0:.0f}s')
